"""Fixed vendor log parser for Flow B repair demo."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Fix Bug 1: Handle malformed rows with missing/empty temperature
            temperature_str = row["temperature_c"]
            if temperature_str == "":
                counts["malformed"] += 1
                continue
            try:
                temperature = float(temperature_str)
            except ValueError:
                counts["malformed"] += 1
                continue

            # Fix Bug 2: Vendor's inclusive 350.0 upper limit - 350.0 is OK, >350.0 is high
            if temperature >= 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
